// The first action of the registry: the engine describes itself (blueprint 3.2, area "Meta").
// Further actions arrive with their service modules (generated by `@app/generators:action`).
import { z } from 'zod';
import { EngineModeSchema } from '../config/env.ts';
import { defineAction } from '../kit/define-action.ts';

export const MetaOutputSchema = z.strictObject({
  engineVersion: z.string(),
  apiVersion: z.literal('v1'),
  mode: EngineModeSchema,
});

export const metaGet = defineAction({
  id: 'meta.get',
  kind: 'query',
  summary: 'Describe the engine: version, API version and delivery mode',
  input: z.strictObject({}),
  output: MetaOutputSchema,
  permission: 'meta.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: () => ({}),
  http: { method: 'GET', path: '/meta' },
  since: '1.0',
});
